import sys

def count_ways(n):
    if n < 0:
        return 0
    if n == 0:
        return 1

    # dp[i] will store the number of ways to reach step i
    dp = [0] * (n + 1)
    dp[0] = 1

    for i in range(1, n + 1):
        # Can reach step i from i-1, i-3, or i-4
        ways = 0
        if i - 1 >= 0:
            ways += dp[i - 1]
        if i - 3 >= 0:
            ways += dp[i - 3]
        if i - 4 >= 0:
            ways += dp[i - 4]
        dp[i] = ways

    return dp[n]

